mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  float r = length(p);
  float a = atan(p.y, p.x) + r * 1.5 - time * 0.5;
  vec2 p_hex = vec2(cos(a), sin(a)) * r;
  vec2 q = abs(p_hex);
  float hex = max(q.x * 0.866025 + q.y * 0.5, q.y);
  float bands = sin(hex * 16.0 - time * 3.0);
  vec3 col = mix(vec3(0.1, 0.05, 0.2), vec3(1.0, 0.6, 0.1), smoothstep(-0.5, 0.8, bands));
  col += vec3(0.8, 0.3, 0.9) * (0.03 / (0.05 + abs(hex - 0.8)));
  col *= (1.0 + 0.3 * bass);
  ret = col;
}
